(
  'bayley-hazen', 'Bayley Hazen', 'Cellars at Jasper Hill',
  'Greensboro', 'Vermont', 'USA',
  'Raw Cow', 'Animal', 'Blue',
  '3-4 months', array['Peppery', 'herbal', 'fruity', 'umami', 'grass', 'hay'],
  'Bayley Hazen Blue is a Jasper Hill Farm original, and is made from our high-quality whole raw milk. It is named for an old military road commissioned by George Washington during the Revolutionary War. Though no major battle ever took place, the road brought Greensboro its first settlers and continues to be used today.', array['Porter or stout', 'Port', 'milk chocolate', 'salads', 'burgers', 'steak'],
